-- Modify "measures" table
ALTER TABLE "seller"."measures" ADD CONSTRAINT "measures_id_basis_key" UNIQUE ("id", "basis");
-- Add columns to "measure_requests" table：basis 由措施回填；既有的 CLOSED 都是措施撤銷時結案的，close_cause 回填 REVOKED（它們都有 admin）。
ALTER TABLE "seller"."measure_requests" ADD COLUMN "basis" text NULL, ADD COLUMN "close_cause" text NULL;
UPDATE "seller"."measure_requests" r SET "basis" = m."basis" FROM "seller"."measures" m WHERE m."id" = r."measure_id";
UPDATE "seller"."measure_requests" SET "close_cause" = 'REVOKED' WHERE "state" = 'CLOSED';
-- Modify "measure_requests" table
ALTER TABLE "seller"."measure_requests" ALTER COLUMN "basis" SET NOT NULL, DROP CONSTRAINT "measure_requests_measure_id_fkey", DROP CONSTRAINT "measure_requests_decision_check", ADD CONSTRAINT "measure_requests_decision_check" CHECK (((state = 'PENDING'::text) AND (decision_reason IS NULL) AND (decided_by_admin_id IS NULL) AND (decided_at IS NULL) AND (close_cause IS NULL)) OR ((state = ANY (ARRAY['ACCEPTED'::text, 'REJECTED'::text])) AND (decision_reason IS NOT NULL) AND ((char_length(decision_reason) >= 1) AND (char_length(decision_reason) <= 2000)) AND (decided_by_admin_id IS NOT NULL) AND (decided_by_admin_id > 0) AND (decided_at IS NOT NULL) AND (decided_at >= submitted_at) AND (close_cause IS NULL)) OR ((state = 'CLOSED'::text) AND (decision_reason IS NULL) AND (close_cause IS NOT NULL) AND ((decided_by_admin_id IS NULL) OR (decided_by_admin_id > 0)) AND ((close_cause <> 'REVOKED'::text) OR (decided_by_admin_id IS NOT NULL)) AND (decided_at IS NOT NULL) AND (decided_at >= submitted_at))), DROP CONSTRAINT "measure_requests_kind_check", ADD CONSTRAINT "measure_requests_kind_check" CHECK (kind = ANY (ARRAY['APPEAL'::text, 'REMEDIATION'::text])), ADD CONSTRAINT "measure_requests_close_cause_check" CHECK (close_cause = ANY (ARRAY['REVOKED'::text, 'ENDED'::text])), ADD CONSTRAINT "measure_requests_remediation_basis_check" CHECK ((kind <> 'REMEDIATION'::text) OR (basis = 'RISK'::text)), ADD CONSTRAINT "measure_requests_measure_basis_fkey" FOREIGN KEY ("measure_id", "basis") REFERENCES "seller"."measures" ("id", "basis") ON UPDATE NO ACTION ON DELETE NO ACTION;
